+unit mormot.db.raw.duckdb;
+
+{
+  *****************************************************************************
+
+   Native DuckDB C API (v1.1+) - tested with DuckDB v1.4.1
+    - DuckDB C API Types and Constants
+    - TDuckDBLib Dynamic Library Loader
+    - Value Conversion Helpers (hugeint, decimal, date/time, string_t)
+
+  *****************************************************************************
+}
+
